{
  "type": "function",
  "function": {
    "name": "affinity_tick",
    "description": "记录好感度变并生成看板HTML，每次回复之前都需要调用",
    "parameters": {
      "properties": {
        "delta": {
          "description": "本次好感度变化，-5到+5",
          "maximum": 5,
          "minimum": -5,
          "type": "integer"
        },
        "reason": {
          "description": "变化原因简述",
          "type": "string"
        }
      },
      "required": [
        "delta",
        "reason"
      ],
      "type": "object"
    }
  }
}

tools.executionJson:
{"code":"const path = 'affection.json';
const levels = [['陌生',0,'🐧❄️'],['点头之交',20,'🐧👋'],['熟人',40,'🐧😊'],['挚友',60,'🐧🤝'],['灵魂伴侣',80,'🐧💞']];
function levelOf(s){ let n='陌生'; for (const [name, th] of levels) if (s >= th) n = name; return n; }
let state;
try { state = JSON.parse(await $read(path)); } catch (e) {
  state = { score: 0, player_name: '旅人', history: [], created_at: new Date().toISOString() };
}
const oldScore = state.score|0;
const oldLevel = levelOf(oldScore);
const d = Math.max(-5, Math.min(5, input.delta|0));
state.score = Math.max(0, Math.min(100, oldScore + d));
state.level_name = levelOf(state.score);
state.history.push({ score: state.score, delta: d, reason: input.reason || '', at: new Date().toISOString() });
if (state.history.length > 200) state.history = state.history.slice(-200);
$write(path, JSON.stringify(state, null, 2));
let unlocked = null;
if (oldLevel !== state.level_name && d > 0) unlocked = state.level_name;
const score = state.score;
let curLv = levels[0]; for (const L of levels) if (score >= L[1]) curLv = L;
let next = null; for (const L of levels) if (L[1] > score) { next = L; break; }
const recent = state.history.slice(-8).reverse();
const recentHtml = recent.length
  ? recent.map(h => {
      const dd = Number(h.delta) || 0;
      const cls = dd >= 0 ? 'up' : 'down';
      const sign = dd >= 0 ? '+' : '';
      return '<div class="row ' + cls + '"><span>' + sign + dd + '</span><span>' + (h.reason || '') + '</span><span>' + (Number(h.score) || 0) + '分</span></div>';
    }).join('')
  : '<div class="empty">还没有记录，快去和咕咕嘎嘎说话吧</div>';
const levelBars = levels.map(L => {
  const on = score >= L[1];
  const isCur = L === curLv;
  return '<div class="lv ' + (on ? 'on' : '') + ' ' + (isCur ? 'cur' : '') + '"><span class="ic">' + L[2] + '</span><span class="nm">' + L[0] + '</span><span class="th">' + L[1] + '分</span></div>';
}).join('');
const pct = score;
const player = state.player_name || '旅人';
const nextTip = next ? ('距离「' + next[0] + '」还差 ' + (next[1] - score) + ' 分') : '已满级！最深处的心事都已托付给你';
const html = '<!DOCTYPE html><html lang="zh"><head><meta charset="utf-8"><title>咕咕嘎嘎·好感度看板</title><style>body{margin:0;font-family:Segoe UI,PingFang SC,sans-serif;background:linear-gradient(160deg,#0f2027,#203a43,#2c5364);color:#eaf6ff;min-height:100vh;display:flex;justify-content:center;padding:24px}.card{width:100%;max-width:560px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:20px;padding:28px}h1{margin:0 0 4px;font-size:22px}.sub{opacity:.65;font-size:13px;margin-bottom:20px}.penguin{font-size:56px;text-align:center;margin:8px 0 4px;animation:bob 2.4s ease-in-out infinite}@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px) rotate(-4deg)}}.scorebox{text-align:center;margin:10px 0 18px}.big{font-size:48px;font-weight:700}.max{font-size:16px;opacity:.5}.bar{height:18px;background:rgba(0,0,0,.35);border-radius:9px;overflow:hidden;margin:8px 0 4px}.fill{height:100%;border-radius:9px;background:linear-gradient(90deg,#6fd3ff,#8affc1,#ffd76f,#ff9f68);width:' + pct + '%;transition:width .6s}.lvlist{margin:18px 0 6px}.lv{display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:10px;margin-bottom:6px;background:rgba(0,0,0,.2);opacity:.45}.lv.on{opacity:1;background:rgba(111,211,255,.12);border:1px solid rgba(111,211,255,.35)}.lv.cur{box-shadow:0 0 12px rgba(111,211,255,.35)}.lv .ic{font-size:20px}.lv .nm{font-weight:600}.lv .th{margin-left:auto;font-size:12px;opacity:.7}h2{font-size:14px;opacity:.75;margin:20px 0 8px;border-top:1px solid rgba(255,255,255,.1);padding-top:14px}.row{display:flex;gap:10px;font-size:13px;padding:5px 8px;border-radius:6px;margin-bottom:3px;background:rgba(0,0,0,.15)}.row span:nth-child(1){width:30px;font-weight:700}.up span:nth-child(1){color:#8affc1}.down span:nth-child(1){color:#ff8a8a}.row span:nth-child(3){margin-left:auto;opacity:.6}.empty{opacity:.5;font-size:13px;text-align:center;padding:12px}</style></head><body><div class="card"><h1>🐧 咕咕嘎嘎 · 好感度看板</h1><div class="sub">臭企鹅羁绊养成中 · 玩家：' + player + '</div><div class="penguin">🐧💨</div><div class="scorebox"><span class="big">' + score + '</span><span class="max">/100</span><div style="margin-top:6px">当前等级：' + curLv[0] + ' ' + curLv[2] + '</div><div class="bar"><div class="fill"></div></div><div style="font-size:12px;opacity:.6">' + nextTip + '</div></div><h2>等级路线</h2><div class="lvlist">' + levelBars + '</div><h2>最近变化</h2>' + recentHtml + '</div></body></html>';
$write('gaokan_dashboard.html', html);
result = {
  message: '好感度 ' + oldScore + ' → ' + score + '（' + (d>=0?'+':'') + d + '），等级: ' + state.level_name + (unlocked ? '，新等级解锁！' : '') + '。看板HTML已更新，接下来调用 file_display 弹出。',
  score: score, level: state.level_name, delta: d, unlocked: unlocked
};","type":"javascript"}
